)

const { graph } = useFilesState(page)
if (graph.problem) return <p className="files-note">{graph.problem}</p>
if (graph.isReading) return <LoadProgressView loadingLabel="Reading the session's graph…" loadingLog={graph.log} />
if (!graph.trees?.length) return <p className="files-note">The graph holds no node of these files.</p>
return (
  <ul className="tree graph-tree" aria-label="Graph">
    {graph.trees.map(tree => (
      <GraphEntryView key={tree.node_id} page={page} entry={tree} />
    ))}
  </ul>
)

const fidelities = this.stages.flatMap(stage => this.practices.map(key => FIDELITIES[stage]![key]).filter((slug): slug is string => Boolean(slug)))
return {
  version: this.version,
  is_stage_chosen: true,
  stages: Object.keys(FIDELITIES).map(name => ({ name, title: name, is_selected: this.stages.includes(name) })),
  practices: PRACTICES.map(practice => ({ ...practice, is_selected: this.practices.includes(practice.key) })),
  formats: [],
  fidelities,
} as GuidanceSelectionData

const below = CHECKOUT_FLOW_NODES.filter(child => child.parent === node.id && this.holds(child, paths))
if (!isOpened) return { node_id: node.id, name: node.name, type: node.type, children: [], children_left_out: below.length }
return { node_id: node.id, name: node.name, type: node.type, children: below.map(child => this.entry(child, paths, false)), children_left_out: 0 }

const spans = new Map<string, [number, number]>()
const widen = (each: SeedNode) => {
  if (each.file) {
    if (!paths.includes(each.file)) return
    const [start, end] = spans.get(each.file) ?? [each.start, each.end]
    spans.set(each.file, [Math.min(start, each.start), Math.max(end, each.end)])
    return
  }
  CHECKOUT_FLOW_NODES.filter(child => child.parent === each.id).forEach(widen)
}
widen(node)
return [...spans].map(([path, [start, end]]) => ({ path, start_line: start, end_line: end, content: '', anchor: `${path}:${start}-${end}` }))

const readWhenStale = () => {
  const { fileBar, graph } = this.store.state
  if (fileBar.view === 'graph' && !graph.isReading && graph.readFor !== this.paths.join('\n')) void this.read()
}
readWhenStale()
return this.store.subscribe(readWhenStale)

const paths = this.paths
const readFor = paths.join('\n')
this.store.change(({ graph }) => ({ graph: { ...graph, readFor, isReading: true, log: [], problem: '' } }))
void this.followProgress(readFor)
try {
  const trees = (await this.session.graphTrees(paths)) ?? []
  this.store.change(({ graph }) => (graph.readFor === readFor ? { graph: { ...graph, trees, branches: {}, isReading: false } } : {}))
  const members = (await this.session.graphMembers()) ?? []
  this.store.change(({ graph }) => (graph.readFor === readFor ? { graph: { ...graph, members } } : {}))
} catch (failure) {
  this.store.change(({ graph }) => ({ graph: { ...graph, isReading: false, problem: `The graph did not read: ${reasonOf(failure)}` } }))
  this.notices.fail(`The Files app did not read the session's graph: ${reasonOf(failure)}`, 'Showing the graph view, calling session.graph_trees')
}

const isUnderWay = () => this.store.state.graph.isReading && this.store.state.graph.readFor === readFor
while (isUnderWay()) {
  const reports = await this.api.post<CddProgress[]>('/cdd/progress', {}).catch(() => null)
  const newest = reports?.at(-1)?.message
  if (newest && isUnderWay()) this.store.change(({ graph }) => (graph.log.at(-1) === newest ? {} : { graph: { ...graph, log: [...graph.log, newest] } }))
  await pause(PROGRESS_EVERY)
}

const isOpen = this.isOpen(entry)
this.store.change(({ graph }) => ({ graph: { ...graph, openNodes: isOpen ? graph.openNodes.filter(id => id !== entry.node_id) : [...graph.openNodes, entry.node_id] } }))
if (isOpen || !entry.children_left_out || this.store.state.graph.branches[entry.node_id]) return
try {
  const branch = await this.session.graphBranch(entry.node_id, this.paths)
  if (branch) this.store.change(({ graph }) => ({ graph: { ...graph, branches: { ...graph.branches, [entry.node_id]: branch } } }))
} catch (failure) {
  this.notices.fail(`The Files app did not open ${entry.name} in the graph: ${reasonOf(failure)}`, 'Opening a node in the graph view, calling session.graph_branch')
}

try {
  const ranges = (await this.session.graphNodeRanges(entry.node_id, this.paths)) ?? []
  if (!ranges.length) return
  const kept = also ? this.store.state.graph.selected.filter(selected => selected.nodeId !== entry.node_id) : []
  const selected = [...kept, ...ranges.map(lines => ({ nodeId: entry.node_id, lines }))]
  this.store.change(({ graph }) => ({ graph: { ...graph, selected } }))
  await this.showNodes(selected)
} catch (failure) {
  this.notices.fail(`The Files app did not open ${entry.name}: ${reasonOf(failure)}`, 'Selecting a node in the graph view, calling session.graph_node_ranges')
}

const found: FileViolationData | undefined = file.violations.find(each => each.violation.rule === rule)
if (!found) return null
return { rule: found.violation.rule, message: found.violation.message, startLine: found.range.start_line, endLine: found.range.end_line }

return (
  <div className="panel" data-testid="practice-graph-tree">
    {loading ? <LoadProgressView loadingLabel={loadingLabel} loadingLog={loadingLog} /> : null}
    {error && !loading ? (
      <div className="scan-error empty-state" data-testid="scan-error">
        <button type="button" className="copy-diagnosis" onClick={() => void copyDiagnosis(error)}>
          Copy for AI
        </button>
        <pre>{error}</pre>
      </div>
    ) : null}
    <ul className="tree">
      {trees.map((node) => (
        <TreeNode key={node.node_id || node.name} node={node} selectedId={selectedId} activeRule={activeRule} onSelect={onSelect} onOpenBranch={onOpenBranch} />
      ))}
    </ul>
  </div>
);

try {
  await navigator.clipboard.writeText(error);
} catch (cause) {
  failures.fail(`The diagnosis was not copied: ${reasonOf(cause)}`, 'Copy for AI in the Graph app');
}

const minutes = Math.floor(seconds / 60);
const rest = seconds % 60;
return `${minutes}:${rest.toString().padStart(2, '0')}`;

const progress = queryProgress(loadingLog);
const log = useRef<HTMLOListElement>(null);
const [elapsed, setElapsed] = useState(0);
useEffect(() => {
  const started = Date.now();
  const id = window.setInterval(() => setElapsed(Math.floor((Date.now() - started) / 1000)), 1000);
  return () => window.clearInterval(id);
}, []);
useEffect(() => {
  const list = log.current;
  if (list) {
    list.scrollTop = list.scrollHeight;
  }
}, [progress.headline, progress.steps.length, loadingLog.length, elapsed]);
const active =
  progress.steps.length === 0 || progress.steps[progress.steps.length - 1]?.name !== progress.headline.split(' ').at(-1);
const headline = progress.headline === 'Loading the graph…' ? loadingLabel ?? progress.headline : progress.headline;
const shown = elapsed > 0 ? `${headline} · ${elapsedLabel(elapsed)}` : headline;
const fraction = progress.total > 0 ? Math.min(100, Math.round((100 * progress.index) / progress.total)) : 0;
return (
  <div className="empty-state work-progress is-working" data-testid="extraction-progress">
    <p className="query-now">{shown}</p>
    {progress.total > 0 ? (
      <div
        className="load-meter"
        data-testid="load-meter"
        role="progressbar"
        aria-valuenow={progress.index}
        aria-valuemin={0}
        aria-valuemax={progress.total}
        aria-label={headline}
      >
        <span style={{ width: `${fraction}%` }} />
      </div>
    ) : null}
    <ol className="loading-log" data-testid="loading-log" ref={log}>
      {progress.steps.map((step) => (
        <li key={`${step.index}-${step.name}`}>
          {step.index}/{step.total} {step.name}
        </li>
      ))}
      {progress.steps.length === 0
        ? (loadingLog.length > 0 ? loadingLog.slice(-12) : [shown]).map((line, index) => <li key={`${index}-${line}`}>{line}</li>)
        : null}
      {active && progress.detail ? <li className="is-current">{progress.detail}</li> : null}
    </ol>
  </div>
);

char = line[index]
if self.quote:
    if char == "\\":
        return 2
    self.quote = "" if char == self.quote else self.quote
elif char in self._QUOTES:
    self.quote = char
elif char in self._OPENING:
    name, step = self._OPENING[char]
    setattr(self, name, getattr(self, name) + step)
    self.opened_call = self.opened_call or char == "("
return 1

path = Path(root, relative) if root else None
text = path.read_text(encoding="utf-8") if path is not None and path.is_file() else ""
end = text.count("\n") + (0 if not text or text.endswith("\n") else 1)
return cls(relative, 1, max(1, end), root)

self.calls = []
for index, line in enumerate(raw.splitlines()):
    self._calls_on_line(line, index + 1)

lines = raw.splitlines()
for call in self.calls:
    index = call.line - 1
    marker = f"/* call:{call.operation} */"
    if 0 <= index < len(lines) and marker not in lines[index]:
        lines[index] = f"{lines[index]} {marker}"
return "\n".join(lines)

if not root or not name:
    return
root_path = Path(root)
function = re.compile(rf"(?:export\s+)?function\s+{re.escape(name)}\b")
constant = re.compile(rf"\bexport\s+const\s+{re.escape(name)}\b")
for path in sorted(files):
    if FileLines.kind(path) is not PathKind.FILE:
        continue
    lines = FileLines.of(path)
    for index, line in enumerate(lines):
        if function.search(line) or constant.search(line):
            end = self._call_end(lines, index) if function.search(line) else self._declaration_end(lines, index)
            self._point_at(path.relative_to(root_path).as_posix(), root, index + 1, end)
            return

depth = _BracketDepth()
for index in range(start, len(lines)):
    depth.read(lines[index])
    if depth.closed and depth.brackets <= 0 and not depth.quote:
        return index + 1
return len(lines)

if not self.root or not self.file or self.file == ".":
    return None
return Path(self.root, self.file)

depth = _BracketDepth()
for index in range(start, len(lines)):
    depth.read(lines[index])
    if depth.opened_call and depth.closed:
        return index + 1
return max(self.end_line, start + 1)

lines = self._file_lines()
if not lines:
    return ""
if self._directory():
    return "\n".join(lines)
return "\n".join(lines[max(0, self.start_line - 1) : self.end_line])

before, kept = list(self.practices), set(self.node_types)
self.select_practices(practices)
if not before or not practices:
    return
added = {node_type for key in practices if key not in before for node_type in self._node_types_of(key)}
self.select_node_types([node_type for node_type in self.node_types if node_type in kept | added])

if self.practices:
    return list(self.practices)
return list(self.graph.practices.opened)

found: list[str] = []
for name in self._scope():
    for node_type in self._node_types_of(name):
        if node_type not in found:
            found.append(node_type)
return found

types = set(self.node_types or self._available_node_types())
found: list[str] = []
for name in self._scope():
    practice = self.graph.practices.opened.get(name)
    if practice is None:
        continue
    ordered = sorted(practice.reading.in_graph.edge_index.types.values(), key=lambda edge_type: edge_type.order)
    for edge_type in ordered:
        if edge_type.kind in found or not edge_type.is_offered:
            continue
        edges = practice.reading.in_graph.edges(edge_type.kind)
        if any(edge.parent.type in types or edge.child.type in types for edge in edges):
            found.append(edge_type.kind)
return found

types = set(self.node_types or self._available_node_types())
found: set[str] = set()
for name in self._scope():
    practice = self.graph.practices.opened.get(name)
    if practice is not None:
        found.update(practice.reading.in_graph.rule_run.rule_labels_for(types))
return sorted(found)

if node.type == "Practice" or node.type == node.name:
    return False
if self.name and node.name != self.name:
    return False
if self.node_types and node.type not in self.node_types:
    return False
if self.practices and node.practice.key not in self.practices:
    return False
if self.violations and not self._fails_selected_rule(node):
    return False
if self.relationships and not self._on_relationship(node):
    return False
return not self.paths or self._under_paths(node.source.file) or self._under_paths(self._named_from_folder(node.source))

if many not in request and one not in request:
    return None
return list(request.get(many) or ([request[one]] if request.get(one) else []))

location = _posix(file)
folders = [_posix(prefix) for prefix in self.paths]
return any(folder and (location == folder or location.startswith(folder + "/")) for folder in folders)

hits = node.failed_rules
if not hits:
    return False
if not self.rules:
    return True
return any(self._label_hits(node, label, hits) for label in self.rules)

for kind in self.relationships:
    for edge in node.practice.reading.in_graph.edges(kind):
        if edge.parent is node or edge.child is node:
            return True
return False

if id(node) in seen:
    return
seen.add(id(node))
chain = [*ancestors, node.name]
if self.matches(node):
    found.append(FilteredNode(node, ancestors, node.rules.chosen(self.violations, list(self.rules))))
for child in node.children:
    self.collect(child, chain, found, seen)

self.data[key] = value
if self.practice is not None and self.practice.reading.in_graph is not None:
    self.practice.reading.in_graph.changed()

node, visited = self, set()
while node is not None and id(node) not in visited:
    if node._holds_attribute(key):
        return getattr(node, key)
    if key in node.data:
        return node.data[key]
    visited.add(id(node))
    node = node.parent or (node.graph.direct_parent(node) if node.practice is not None else None)
return default

merged = sorted(set(self.get_fact(key) or []) | set(values))
if key in self.graph_facts:
    setattr(self, key, merged)
else:
    self.set_fact(key, merged)

types = {self.type}
anchor = self.schema.anchor_type(self.type)
if anchor:
    types.add(anchor)
return types

pending: list[Iterator[tuple[Node, Node | None]]] = [iter([(self, parent)])]
while pending:
    step = next(pending[-1], None)
    if step is None:
        pending.pop()
        continue
    node, holder = step
    if node._placed_under(holder):
        pending.append(node._placements())

if parent is not None:
    parent.children.append(self)
    if self.parent is None or (self._holder(self.parent) and not self._holder(parent)):
        self.parent = parent
if self._populated:
    return False
self._populated = True
return True

types = sorted((edge_type for edge_type in self.practice.reading.in_graph.edge_index.types.values() if edge_type.is_offered), key=lambda edge_type: edge_type.order)
for edge_type in types:
    for edge in self._edges_in_source_order(edge_type.kind):
        yield edge.child, self if edge.display == "direct" else self._holder_for(edge.kind)

for child in self.children:
    if child.name == name:
        return child
return None

seen = set() if seen is None else seen
stack = set() if stack is None else stack
if self.node_id in stack:
    return ExplorerEntry(self)
home = via is None or via is self.parent
first_home = home and self.node_id not in seen
children = self.children if first_home else []
if first_home:
    seen.add(self.node_id)
path = stack | {self.node_id}
written = [child.serialize(seen, self, path) for child in children]
if first_home:
    category = self.rule_category()
    if category is not None:
        written.append(category)
return ExplorerEntry(self, written)

if self.type == self.name or self.type == "Practice":
    return None
return self.rules if self.rules.shown else None

node = self.graph.node(node_id)
if node is None:
    return None
return NodeSource(node, members=self.source_members())

declared = list(self.graph.practices.opened.values())
classes = {node_type for practice in declared for node_type in practice.reading.class_types}
members = {node_type for practice in declared for node_type in practice.reading.member_types}
found = (node for practice in declared for node in practice.reading.in_graph.nodes() if node.type in classes | members)
return [NodeSource(node, owner="" if node.type in classes else str(node.get_fact("owner", "") or "")) for node in found]

node = self.graph.node(node_id)
if node is None:
    return None
kept = node.serialize(via=node.parent).kept_by(self.filter.narrowed_by(request))
return kept.opened() if kept is not None else ExplorerEntry(node)

if type is not None:
    return list(self._nodes.get(type, []))
return [node for group in self._nodes.values() for node in group]

root = self._source_root.resolve() if self._source_root is not None else self.graph.scope.folder
if root is None:
    return set()
return {file.relative_to(root).as_posix() for file in files if file == root or root in file.parents}

if dropped:
    self.changed()
    self._by_id = {node_id: node for node_id, node in self._by_id.items() if id(node) not in dropped}
    self._nodes = {kind: [node for node in group if id(node) not in dropped] for kind, group in self._nodes.items()}
return dropped

self.changed()
for node in self._by_id.values():
    node.forget_rules()

for node in self._by_id.values():
    node.leave_tree()
self.root.populate()

practice = self._part.practice
checks = list(practice.reading.checks().values())
if not checks:
    return
context = RuleCheckContext(practice, self._part.source_root_path)
for index, check in enumerate(checks, start=1):
    report_progress(f"{practice.key} · rule {check.slug} · {index}/{len(checks)}")
    for node_id, message in check.check_practice(context):
        node = self._part.graph.node(node_id)
        if node is not None:
            node.rules.record_violation(check.slug, message)
self._check_each_node(context)

covering = self._covering_classes()
nodes = self._part.nodes()
key = self._part.practice.key
for index, node in enumerate(nodes, start=1):
    report_progress(f"{key} · rules · {index}/{len(nodes)} · {node.type} {node.name}")
    skipped = {slug for slugs, spans in covering for slug in slugs if _inside(node, spans)}
    for rule in node.rules:
        if not rule.runs or rule.slug in skipped:
            continue
        for message in rule.check(node, context):
            node.rules.record_violation(rule.slug, message)

found = []
for other in self._part.graph.practices.opened.values():
    class_type = other.reading.class_node_type
    if other is self._part.practice or not class_type:
        continue
    spans: dict[str, list[tuple[int, int]]] = {}
    for node in other.reading.in_graph.nodes(class_type):
        if node.source.file:
            spans.setdefault(node.source.file.replace("\\", "/"), []).append((node.source.start_line, node.source.end_line))
    found.append((frozenset(other.reading.checks()), spans))
return found

part = self._part
if saved.source_root:
    part.source_root_path = Path(saved.source_root)
part.root.data.update(saved.root_facts)
for kept in saved.nodes:
    if not part.holds(kept.node_id):
        part.take_saved(kept)

part = self._part
if changes.dropped_edges:
    named = set(changes.dropped_edges)
    part.drop_edges(lambda edge: (edge.kind, edge.parent.node_id, edge.child.node_id) in named)
dropped = set(changes.dropped_nodes)
part.forget({id(node) for node in part.nodes() if node.node_id in dropped})
for kept in changes.nodes:
    part.take_saved(kept)
if changes.root_facts is not None:
    part.root.data = dict(changes.root_facts)

graph = self._part.graph
for kept in saved.edges:
    parent, child = graph.node(kept.parent), graph.node(kept.child)
    if parent is not None and child is not None:
        graph.record(kept.type, parent, child)
for node_id, hits in saved.violations_by_node.items():
    node = graph.node(node_id)
    if node is not None:
        node.forget_rules()
        for violation in hits:
            node.rules.restore(violation)

file = (node.source.file or "").replace("\\", "/")
start, end = node.source.start_line, node.source.end_line
return any(start <= class_end and class_start <= end for class_start, class_end in spans.get(file, ()))

with self._changing:
    roots = {practice: root for practice in self.practices.held.values() if (root := practice.session_root) is not None and root.is_dir()}
    if not roots:
        return GraphLoaded("No practice root of a session is there to read, so nothing was loaded.")
    self.scope = LoadScope(self.scope.folder)
    self.practices.choose(roots)
    return self.build.load(False, call)

with self._changing:
    folder = self.scope.folder
    if folder is None:
        return
    roots = {practice: root if (root := practice.session_root) is not None and root.is_dir() else Path(folder) for practice in self.practices.held.values()}
    if self.scope.over_whole and self.practices.roots_by_key == {practice.key: root for practice, root in roots.items()}:
        return
    self.scope = LoadScope(folder)
    self.practices.choose(roots)
    self.build.load(False, call)

if self.scope.folder is None:
    return GraphSaved("")
saved_file = self.saved_file
return GraphSaved(str(saved_file.write(SavedGraph.from_graph(self).merged_over(saved_file.read()))))

root = self.applied_patterns.root_of(folder)
if not (root / "practices").is_dir():
    raise GraphFailure("overlay_of", f"Not an overlay root (missing practices/): {folder}")
return Overlay(str(root))

found = {name: getattr(self, name) for name in self.graph_facts if hasattr(self, name)}
found.update(self.data)
return found

if self._rules is None:
    self._rules = GraphRulesCollection.from_node(self)
return self._rules

if self._root is None:
    raise GraphFailure("root", f"{self.practice.key} is not open in this graph")
return self._root
